import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Testing-data-consistency.md","filePath":"manual-en/Testing-data-consistency.md","lastUpdated":1785684581000}'),o={name:"manual-en/Testing-data-consistency.md"};function r(i,t,d,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h4 id="_5-2-4-testing-data-consistency" tabindex="-1">5.2.4 Testing data consistency <a class="header-anchor" href="#_5-2-4-testing-data-consistency" aria-label="Permalink to &quot;5.2.4 Testing data consistency&quot;">​</a></h4><p>A sensible check to perform on survey data is the calculation of reliability. This gives the statistician some confidence that the questionnaires have been completed thoughtfully. If you examine the labels of variables <strong>v1</strong> , <strong>v3</strong> and <strong>v4</strong> , you will notice that they ask very similar questions. One would therefore expect the values of these variables (after recoding) to closely follow one another, and we can test that with the <code>RELIABILITY</code> command (see <a href="./RELIABILITY">RELIABILITY</a>). The following example shows a PSPP session where the user recodes negatively scaled variables and then requests reliability statistics for <strong>v1</strong> , <strong>v3</strong> , and <strong>v4</strong>.</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/hotel.sav&#39;.
PSPP&gt; compute v3 = 6 - v3.
PSPP&gt; compute v5 = 6 - v5.
PSPP&gt; reliability v1, v3, v4.
</code></pre><p>This yields the following output:</p><table tabindex="0"><thead><tr><th>Cases</th><th>N</th><th>Percent</th></tr></thead><tbody><tr><td>Valid</td><td>17</td><td>100.0%</td></tr><tr><td>Excluded</td><td>0</td><td>.0%</td></tr><tr><td>Total</td><td>17</td><td>100.0%</td></tr><tr><td>Cronbach&#39;s Alpha</td><td>N of Items</td><td></td></tr><tr><td>.81</td><td>3</td><td></td></tr></tbody></table><p>As a rule of thumb, many statisticians consider a value of Cronbach’s Alpha of 0.7 or higher to indicate reliable data.</p><p>Here, the value is 0.81, which suggests a high degree of reliability among variables <strong>v1</strong> , <strong>v3</strong> and <strong>v4</strong> , so the data and the recoding that we performed are vindicated.</p>`,7)])])}const u=e(o,[["render",r]]);export{p as __pageData,u as default};
